<?php require_once __DIR__.'/../includes/auth.php'; header('Content-Type: application/json'); if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['success'=>false,'message'=>'POST required']);exit;} $phone=preg_replace('/[^0-9+]/','',trim($_POST['phone']??''));$normalized=preg_replace('/^\+91/','',$phone);if(!preg_match('/^[6-9][0-9]{9}$/',$normalized)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Enter a valid 10-digit Indian mobile number.']);exit;}if(($_POST['action']??'')==='request'){echo json_encode(['success'=>true,'message'=>'Demo OTP is 111000. No SMS was sent.']);exit;}if(($_POST['action']??'')!=='verify'||($_POST['otp']??'')!=='111000'){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Invalid demo OTP.']);exit;}try{$s=db()->prepare('INSERT INTO citizens(phone,full_name,verified_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE verified_at=NOW()');$s->execute([$normalized,'Citizen']);$id=(int)db()->lastInsertId();if(!$id){$q=db()->prepare('SELECT id FROM citizens WHERE phone=?');$q->execute([$normalized]);$id=(int)$q->fetchColumn();}$_SESSION['citizen_id']=$id;$_SESSION['citizen_phone']=$normalized;$_SESSION['citizen_name']='Citizen';echo json_encode(['success'=>true,'message'=>'Verified']);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'message'=>'Database is not ready.']);}